mapper.select:
SELECT s.id, s.name, s.voltage_level AS voltageLevel, s.commission_date AS commissionDate, s.run_status AS runStatus, s.jurisdiction_years AS jurisdictionYears, s.management_level AS managementLevel, s.area_id AS areaId, a.area_name AS areaName FROM substation s LEFT JOIN power_area a ON s.area_id = a.id
s.deleted = 0
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.voltage_level = #{voltageLevel}
AND s.run_status = #{runStatus}
AND s.area_id = #{areaId}
AND s.management_level = #{managementLevel}
ORDER BY s.create_time ASC

SELECT * FROM substation

    deleted = 0

        AND name LIKE CONCAT('%', #{name}, '%')


        AND voltage_level = #{voltageLevel}


        AND run_status = #{runStatus}


ORDER BY ${sortField} ${sortOrder} LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM substation

    deleted = 0

        AND name LIKE CONCAT('%', #{name}, '%')


        AND voltage_level = #{voltageLevel}


        AND run_status = #{runStatus}
